--- Board/profile capabilities generated by the image builder.
--
-- The manifest is intentionally a small key/value file rather than JSON so
-- it can be read without adding another runtime dependency. Defaults keep a
-- legacy/full image usable when the generated file is absent. The SQM marker
-- remains authoritative for legacy preserve-upgrade cases.
local M = {}

local CAPABILITIES_FILE = os.getenv("KEMOFI_CAPABILITIES_FILE") or
  "/etc/kemofi/capabilities"
local SQM_DISABLED_FILE = "/etc/kemofi/sqm-disabled"
local cached = nil

local DEFAULTS = {
  profile = "unknown",
  flavor = "full",
  resource_tier = "standard",
  radio_bands = "unknown",
  sqm_available = true,
  roaming_available = true,
  remote_available = true,
  captive_portal_available = true,
  admin_available = true,
  coin_poll_ms = 250,
  status_poll_ms = 5000
}

local function trim(value)
  return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local function file_present(path)
  local file = io.open(path, "r")
  if not file then return false end
  file:close()
  return true
end

local function parse_value(default, value)
  if type(default) == "boolean" then
    return value == "1" or value == "true"
  elseif type(default) == "number" then
    return tonumber(value) or default
  end
  return value
end

local function load()
  if cached then return cached end

  local result = {}
  for key, value in pairs(DEFAULTS) do result[key] = value end

  local file = io.open(CAPABILITIES_FILE, "r")
  if file then
    for line in file:lines() do
      local key, value = line:match("^([%w_]+)=(.*)$")
      if key and result[key] ~= nil then
        result[key] = parse_value(result[key], trim(value))
      end
    end
    file:close()
  end

  -- A preserved database can contain old SQM settings. The build marker is
  -- the final authority and prevents stale state from exposing SQM controls.
  if file_present(SQM_DISABLED_FILE) then
    result.sqm_available = false
  end

  cached = result
  return cached
end

function M.get()
  return load()
end

function M.reload()
  cached = nil
  return load()
end

return M
